import logo from './logo.svg';
import React,{useState,useEffect} from 'react';
import './App.css';
import "bootstrap/dist/css/bootstrap.min.css";
import "bootstrap/dist/js/bootstrap.bundle.min";

function App() {
  const [userName,setUserName]=useState("");
  const [pwd,setPwd]=useState("");
  const [value,setValue]=useState("");

  useEffect(()=>{
    if(userName!==""&&pwd!=="" && userName==="admin" && pwd==="admin123"){
      setValue(true);
    }
    else{
      setValue(false);
    }    
  },[userName,pwd]);//Use Effect Dependency

  const update=()=>{
    if(value){
      alert("Login Success");
    }
    else{
      alert("Login Failed");
    }
  }
  return (
    <div className='container'>
      <form onSubmit={update}>
        {/* Login Form container */}
        <div className='Login-form'>
          <div className='form-title'>
            <span>Sign In</span>
          </div>
          <div className='form-inputs'>
            <div className='input-box'>
               <input type="text" className="input-field" onChange={(e)=>(setUserName(e.target.value))} placeholder='Username' required/>
              <i className='bx bx-user-alt icon'></i>
            </div>
            <div className='input-box'>
               <input type="password" className="input-field" onChange={(e)=>(setPwd(e.target.value))} placeholder='Password' required/>
              <i className='bx bx-lock-alt icon'></i>
            </div>
            <div className='forget-pass'>
              <a href="#">Forget Password</a>
            </div>
            <div className='input-box'>
              <button className='input-submit'>
                <span>Sign In</span>
                <i className='bx bx-right-arror-alt'></i>
              </button>
            </div>
          </div>
        </div>


        <input type="submit"/>
      </form>
    </div>
  );
}

export default App;
